define class Flat as pub let int value = 42; end
pub fnc main(): int {
    let mut Flat a = new Flat();
    let mut Flat b = copy! a;
    b.value = 99;
    return a.value;
}

define class Flat as pub let int value = 42; end
pub fnc main(): int {
    let mut Flat a = new Flat();
    val b = copy!! a;
    return b.value;
}

define class Flat implements DeepCopyable<Flat> as pub let int value = 42; end
pub fnc main(): int {
    let mut Flat a = new Flat();
    let mut Flat b = copy!! a;
    b.value = 99;
    return a.value;
}

