define class Person as
    pub let int age = 25;
    pub let Array<int> scores = new Array<int>();
end
pub fnc main(): int {
    let mut Person a = new Person();
    a.scores.add(10);
    block {
        val b = copy! a;
        if b.scores.get(0) != 10 do return 0; fi
    }
    a.scores.set(0, 42);
    return a.scores.get(0);
}

