define class Person as
    pub let int age = 25;
    pub let Array<int> scores = new Array<int>();
end
fnc escape(Person a): Person { block { val b = copy! a; return b; } }
pub fnc main(): int { return 42; }

define class Person implements DeepCopyable<Person> as
    pub let int age = 25;
    pub let Array<int> scores = new Array<int>();
end
pub fnc main(): int {
    let mut Person a = new Person();
    a.scores.add(10);
    let mut Person b = copy!! a;
    b.scores.set(0, 99);
    return a.scores.get(0) + 32;
}
